question.template:
""" Protótipo UniCV: pergunta de fluxograma com as figuras e as regras do Flowgorithm. O estudante constrói o fluxograma (com funções, se quiser) e o corretor executa-o com os dados de cada caso de teste, comparando o que ele escreve com a saída esperada.
Parâmetros do modelo (todos opcionais): max_passos número máximo de figuras executadas por teste (por omissão 100000) exigir lista de figuras que o fluxograma tem de usar: "entrada", "saida", "declarar", "atribuicao", "chamar", "se", "enquanto", "para", "fazer", "comentario" e "ciclo" (qualquer um dos três ciclos) proibir lista de figuras que o fluxograma não pode usar funcoes lista de nomes de funções que o estudante tem de definir lang língua das mensagens quando o estudante não escolheu outra no editor: "pt" (por omissão), "en" ou "es" """ import json import math import random import re import sys
__answer__ = """{{ STUDENT_ANSWER | e('py') }}""" __params__ = json.loads("""{{ QUESTION.parameters | json_encode | e('py') }}""")
MENSAGENS = { 'pt': { 'figura': "{nome} «{texto}»", 'figura_vazia': "{nome} (vazia)", 'na_funcao': "Na função {f}, {onde}", 'em': "{onde}: {erro}.", 'tipos_nomes': {'integer': 'Inteiro', 'real': 'Real', 'string': 'Texto', 'boolean': 'Lógico'}, 'figuras': {'input': 'Entrada', 'output': 'Saída', 'declare': 'Declarar', 'assign': 'Atribuição', 'call': 'Chamar', 'if': 'Se', 'while': 'Enquanto', 'for': 'Para', 'do': 'Fazer', 'comment': 'Comentário'}, 'ciclo': 'de ciclo (Enquanto, Para ou Fazer)', 'ate': 'até', 'ate_desc': 'descendo até', 'palavra_passo': 'passo', 'sem_conteudo': "falta preencher a figura", 'falta_campo': "falta {campo}", 'campo_variavel': "a variável", 'campo_expressao': "a expressão", 'campo_inicio': "o valor inicial", 'campo_fim': "o valor final", 'campo_tamanho': "o tamanho do vetor", 'campo_nomes': "o nome das variáveis", 'simbolo': "símbolo não reconhecido: '{s}'", 'aspas': "falta fechar as aspas de um texto", 'sublinhado': "'{n}': os nomes não podem ter o carácter _", 'mal_escrita': "expressão mal escrita", 'nome_invalido': "'{n}' não é um nome válido (deve começar por uma letra e ter só letras e algarismos)", 'reservada': "'{n}' é uma palavra reservada e não pode ser usada como nome", 'nao_declarada': "a variável '{n}' não foi declarada", 'ja_declarada': "a variável '{n}' já foi declarada", 'sem_valor': "a variável '{n}' é usada antes de ter um valor", 'elemento_sem_valor': "o elemento {i} do vetor '{n}' é usado antes de ter um valor", 'nao_e_vetor': "'{n}' não é um vetor", 'vetor_sem_indice': "'{n}' é um vetor: indique a posição entre parênteses retos", 'indice_inteiro': "a posição de um vetor tem de ser um número inteiro", 'indice_fora': "a posição {i} não existe no vetor '{n}' (as posições vão de 0 a {m})", 'tamanho_invalido': "o tamanho de um vetor tem de ser um número inteiro maior do que zero", 'destino': "aqui deve vir o nome de uma variável (ou de uma posição de um vetor)", 'tipo_atribuicao': "não se pode guardar um valor {de} numa variável {para}", 'op_numeros': "o operador {op} só funciona com números", 'op_logicos': "o operador {op} só funciona com valores lógicos", 'comparar': "não se pode comparar um valor {a} com um valor {b}", 'condicao': "a condição tem de dar um valor lógico (true ou false)", 'divisao_zero': "divisão por zero", 'impossivel': "operação impossível com estes valores", 'funcao_desconhecida': "a função '{n}' não existe", 'num_args': "a função '{n}' recebe {k} argumento(s), mas foram dados {d}", 'arg_tipo': "a função '{n}' não aceita um valor {t} neste argumento", 'arg_vetor': "o argumento {k} da função '{n}' tem de ser um vetor de {t}", 'sem_retorno': "a função '{n}' não devolve nenhum valor e não pode ser usada numa expressão", 'chamar_so_funcoes': "numa figura Chamar só se pode chamar uma função definida no fluxograma", 'retorno_nao_declarado': "a variável devolvida '{n}' não foi declarada na função", 'retorno_sem_valor': "a variável devolvida '{n}' não tem valor no fim da função", 'recursao': "chamadas de funções encadeadas demais (recursão sem fim?)", 'entrada_tipo': "o valor lido «{v}» não é {t}", 'entrada_tipos': {'integer': 'um número inteiro', 'real': 'um número', 'boolean': 'true nem false'}, 'mais_dados': "o fluxograma pede mais dados do que os que existem neste teste", 'para_variavel': "a variável de uma figura Para tem de ser Inteiro ou Real", 'passo': "o passo de uma figura Para tem de ser um número maior do que zero", 'nao_termina': "O fluxograma não termina: verifique se a condição do ciclo chega a ser falsa.", 'ilegivel': "Não foi possível ler o fluxograma.", 'vazio': "O fluxograma está vazio: acrescente figuras entre o Início e o Fim.", 'funcao_nome': "Há uma função com um nome inválido: '{n}'.", 'funcao_repetida': "Há duas funções com o nome '{n}'.", 'param_nome': "A função {f} tem um parâmetro com um nome inválido ou repetido: '{n}'.", 'retorno_nome': "A função {f} devolve um valor, mas falta indicar a variável devolvida.", 'exigir': "O fluxograma deve usar pelo menos uma figura {nome}.", 'proibir': "Neste exercício o fluxograma não pode usar figuras {nome}.", 'exigir_funcao': "O fluxograma deve definir uma função chamada {n}.", }, 'en': { 'figura': "{nome} «{texto}»", 'figura_vazia': "{nome} (empty)", 'na_funcao': "In function {f}, {onde}", 'em': "{onde}: {erro}.", 'tipos_nomes': {'integer': 'Integer', 'real': 'Real', 'string': 'String', 'boolean': 'Boolean'}, 'figuras': {'input': 'Input', 'output': 'Output', 'declare': 'Declare', 'assign': 'Assign', 'call': 'Call', 'if': 'If', 'while': 'While', 'for': 'For', 'do': 'Do', 'comment': 'Comment'}, 'ciclo': 'loop (While, For or Do)', 'ate': 'to', 'ate_desc': 'down to', 'palavra_passo': 'step', 'sem_conteudo': "the shape has not been filled in", 'falta_campo': "{campo} is missing", 'campo_variavel': "the variable", 'campo_expressao': "the expression", 'campo_inicio': "the start value", 'campo_fim': "the end value", 'campo_tamanho': "the array size", 'campo_nomes': "the variable names", 'simbolo': "unrecognised symbol: '{s}'", 'aspas': "a string is missing its closing quotes", 'sublinhado': "'{n}': names cannot contain the _ character", 'mal_escrita': "badly written expression", 'nome_invalido': "'{n}' is not a valid name (it must start with a letter and have only letters and digits)", 'reservada': "'{n}' is a reserved word and cannot be used as a name", 'nao_declarada': "the variable '{n}' has not been declared", 'ja_declarada': "the variable '{n}' has already been declared", 'sem_valor': "the variable '{n}' is used before it has a value", 'elemento_sem_valor': "element {i} of the array '{n}' is used before it has a value", 'nao_e_vetor': "'{n}' is not an array", 'vetor_sem_indice': "'{n}' is an array: give the index in square brackets", 'indice_inteiro': "an array index must be an integer", 'indice_fora': "index {i} does not exist in the array '{n}' (indexes go from 0 to {m})", 'tamanho_invalido': "the size of an array must be an integer greater than zero", 'destino': "the name of a variable (or of an array element) is expected here", 'tipo_atribuicao': "a {de} value cannot be stored in a {para} variable", 'op_numeros': "the operator {op} only works with numbers", 'op_logicos': "the operator {op} only works with Boolean values", 'comparar': "a {a} value cannot be compared with a {b} value", 'condicao': "the condition must give a Boolean value (true or false)", 'divisao_zero': "division by zero", 'impossivel': "operation impossible with these values", 'funcao_desconhecida': "the function '{n}' does not exist", 'num_args': "the function '{n}' takes {k} argument(s), but {d} were given", 'arg_tipo': "the function '{n}' does not accept a {t} value in this argument", 'arg_vetor': "argument {k} of the function '{n}' must be an array of {t}", 'sem_retorno': "the function '{n}' does not return a value and cannot be used in an expression", 'chamar_so_funcoes': "a Call shape can only call a function defined in the flowchart", 'retorno_nao_declarado': "the return variable '{n}' has not been declared in the function", 'retorno_sem_valor': "the return variable '{n}' has no value at the end of the function", 'recursao': "too many nested function calls (endless recursion?)", 'entrada_tipo': "the value read «{v}» is not {t}", 'entrada_tipos': {'integer': 'an integer', 'real': 'a number', 'boolean': 'true or false'}, 'mais_dados': "the flowchart asks for more data than this test has", 'para_variavel': "the variable of a For shape must be Integer or Real", 'passo': "the step of a For shape must be a number greater than zero", 'nao_termina': "The flowchart does not end: check that the loop condition eventually becomes false.", 'ilegivel': "The flowchart could not be read.", 'vazio': "The flowchart is empty: add shapes between Main and End.", 'funcao_nome': "There is a function with an invalid name: '{n}'.", 'funcao_repetida': "There are two functions called '{n}'.", 'param_nome': "The function {f} has a parameter with an invalid or repeated name: '{n}'.", 'retorno_nome': "The function {f} returns a value, but the return variable is missing.", 'exigir': "The flowchart must use at least one {nome} shape.", 'proibir': "In this exercise the flowchart cannot use {nome} shapes.", 'exigir_funcao': "The flowchart must define a function called {n}.", }, 'es': { 'figura': "{nome} «{texto}»", 'figura_vazia': "{nome} (vacía)", 'na_funcao': "En la función {f}, {onde}", 'em': "{onde}: {erro}.", 'tipos_nomes': {'integer': 'Entero', 'real': 'Real', 'string': 'Cadena', 'boolean': 'Lógico'}, 'figuras': {'input': 'Entrada', 'output': 'Salida', 'declare': 'Declarar', 'assign': 'Asignar', 'call': 'Llamar', 'if': 'Si', 'while': 'Mientras', 'for': 'Para', 'do': 'Hacer', 'comment': 'Comentario'}, 'ciclo': 'de ciclo (Mientras, Para o Hacer)', 'ate': 'hasta', 'ate_desc': 'bajando hasta', 'palavra_passo': 'paso', 'sem_conteudo': "falta rellenar la figura", 'falta_campo': "falta {campo}", 'campo_variavel': "la variable", 'campo_expressao': "la expresión", 'campo_inicio': "el valor inicial", 'campo_fim': "el valor final", 'campo_tamanho': "el tamaño del arreglo", 'campo_nomes': "el nombre de las variables", 'simbolo': "símbolo no reconocido: '{s}'", 'aspas': "falta cerrar las comillas de una cadena", 'sublinhado': "'{n}': los nombres no pueden tener el carácter _", 'mal_escrita': "expresión mal escrita", 'nome_invalido': "'{n}' no es un nombre válido (debe empezar por una letra y tener solo letras y dígitos)", 'reservada': "'{n}' es una palabra reservada y no puede usarse como nombre", 'nao_declarada': "la variable '{n}' no ha sido declarada", 'ja_declarada': "la variable '{n}' ya ha sido declarada", 'sem_valor': "la variable '{n}' se usa antes de tener un valor", 'elemento_sem_valor': "el elemento {i} del arreglo '{n}' se usa antes de tener un valor", 'nao_e_vetor': "'{n}' no es un arreglo", 'vetor_sem_indice': "'{n}' es un arreglo: indique la posición entre corchetes", 'indice_inteiro': "la posición de un arreglo tiene que ser un número entero", 'indice_fora': "la posición {i} no existe en el arreglo '{n}' (las posiciones van de 0 a {m})", 'tamanho_invalido': "el tamaño de un arreglo tiene que ser un número entero mayor que cero", 'destino': "aquí debe ir el nombre de una variable (o de una posición de un arreglo)", 'tipo_atribuicao': "no se puede guardar un valor {de} en una variable {para}", 'op_numeros': "el operador {op} solo funciona con números", 'op_logicos': "el operador {op} solo funciona con valores lógicos", 'comparar': "no se puede comparar un valor {a} con un valor {b}", 'condicao': "la condición tiene que dar un valor lógico (true o false)", 'divisao_zero': "división por cero", 'impossivel': "operación imposible con estos valores", 'funcao_desconhecida': "la función '{n}' no existe", 'num_args': "la función '{n}' recibe {k} argumento(s), pero se dieron {d}", 'arg_tipo': "la función '{n}' no acepta un valor {t} en este argumento", 'arg_vetor': "el argumento {k} de la función '{n}' tiene que ser un arreglo de {t}", 'sem_retorno': "la función '{n}' no devuelve ningún valor y no puede usarse en una expresión", 'chamar_so_funcoes': "en una figura Llamar solo se puede llamar a una función definida en el diagrama", 'retorno_nao_declarado': "la variable devuelta '{n}' no ha sido declarada en la función", 'retorno_sem_valor': "la variable devuelta '{n}' no tiene valor al final de la función", 'recursao': "demasiadas llamadas de funciones encadenadas (¿recursión sin fin?)", 'entrada_tipo': "el valor leído «{v}» no es {t}", 'entrada_tipos': {'integer': 'un número entero', 'real': 'un número', 'boolean': 'true ni false'}, 'mais_dados': "el diagrama pide más datos de los que hay en esta prueba", 'para_variavel': "la variable de una figura Para tiene que ser Entero o Real", 'passo': "el paso de una figura Para tiene que ser un número mayor que cero", 'nao_termina': "El diagrama no termina: compruebe que la condición del ciclo llega a ser falsa.", 'ilegivel': "No se pudo leer el diagrama de flujo.", 'vazio': "El diagrama está vacío: añada figuras entre Principal y Fin.", 'funcao_nome': "Hay una función con un nombre no válido: '{n}'.", 'funcao_repetida': "Hay dos funciones con el nombre '{n}'.", 'param_nome': "La función {f} tiene un parámetro con un nombre no válido o repetido: '{n}'.", 'retorno_nome': "La función {f} devuelve un valor, pero falta indicar la variable devuelta.", 'exigir': "El diagrama debe usar al menos una figura {nome}.", 'proibir': "En este ejercicio el diagrama no puede usar figuras {nome}.", 'exigir_funcao': "El diagrama debe definir una función llamada {n}.", }, }
LINGUA = __params__.get('lang') if __params__.get('lang') in MENSAGENS else 'pt'
def msg(chave, **dados): return MENSAGENS[LINGUA][chave].format(**dados)
class Erro(Exception): """Um erro a mostrar ao estudante. Os erros 'completos' já dizem onde aconteceram; os outros recebem a indicação da figura. """
def __init__(self, chave, completo=False, **dados): super().__init__(msg(chave, **dados)) self.completo = completo
class Fim(Exception): """O limite de passos foi atingido."""
# ----- Palavras e nomes -----
RESERVADAS = {'and', 'false', 'mod', 'not', 'or', 'pi', 'true', 'boolean', 'integer', 'real', 'string', 'arccosh', 'cosh', 'arcsinh', 'sinh', 'arctanh', 'tanh', 'eof'} TIPOS = ('integer', 'real', 'string', 'boolean')
def nome_tipo(tipo): return MENSAGENS[LINGUA]['tipos_nomes'][tipo]
def tipo_de(valor): if isinstance(valor, bool): return 'boolean' if isinstance(valor, int): return 'integer' if isinstance(valor, float): return 'real' return 'string'
def numero(valor): return isinstance(valor, (int, float)) and not isinstance(valor, bool)
def formatar(valor): """O texto com que um valor é escrito, como no Flowgorithm.""" if isinstance(valor, bool): return 'true' if valor else 'false' if isinstance(valor, float): if valor.is_integer() and abs(valor) < 1e15: return str(int(valor)) return format(valor, '.15g') return str(valor)
def verificar_nome(nome): """Garante que o nome segue as regras dos identificadores.""" if '_' in nome: raise Erro('sublinhado', n=nome) if not nome or not nome[0].isalpha() or not all(c.isalpha() or c.isdigit() for c in nome): raise Erro('nome_invalido', n=nome) if nome.lower() in RESERVADAS or nome.lower() in INTRINSECAS: raise Erro('reservada', n=nome) return nome
# ----- Expressões -----
TOKEN = re.compile(r''' (?P<texto>"[^"]*") | (?P<aberto>") | (?P<numero>\d+\.\d+|\d+) | (?P<nome>[^\W\d]\w*) | (?P<op>==|!=|<>|<=|>=|&&|\|\||[-+*/%^&<>=!()\[\],≤≥≠¬∧∨×÷↑π]) | (?P<espaco>\s+) | (?P<outro>.) ''', re.VERBOSE)
SINONIMOS = {'=': '==', '<>': '!=', '≠': '!=', '≤': '<=', '≥': '>=', '!': 'not', '¬': 'not', '&&': 'and', '∧': 'and', '||': 'or', '∨': 'or', '×': '*', '÷': '/', 'mod': '%', '↑': '^'} PRECEDENCIA = {'or': 1, 'and': 2, '==': 3, '!=': 3, '<': 3, '<=': 3, '>': 3, '>=': 3, '&': 4, '+': 5, '-': 5, '*': 6, '/': 6, '%': 6, '^': 7}
def tokens(texto): resultado = [] for m in TOKEN.finditer(texto): tipo, valor = m.lastgroup, m.group() if tipo == 'espaco': continue if tipo == 'aberto': raise Erro('aspas') if tipo == 'outro': raise Erro('simbolo', s=valor) if tipo == 'nome': if '_' in valor: raise Erro('sublinhado', n=valor) minusculas = valor.lower() if minusculas in ('and', 'or', 'not', 'mod'): tipo, valor = 'op', SINONIMOS.get(minusculas, minusculas) elif tipo == 'op': valor = SINONIMOS.get(valor, valor) resultado.append((tipo, valor)) return resultado
class Analisador: """Converte o texto de uma expressão numa árvore: ('num', v) ('str', s) ('bool', b) ('var', nome) ('idx', nome, e) ('call', nome, [e...]) ('un', op, e) ('bin', op, e1, e2) """
def __init__(self, texto): self.toks = tokens(texto) self.i = 0
def ver(self): return self.toks[self.i] if self.i < len(self.toks) else (None, None)
def tirar(self): tok = self.ver() self.i += 1 return tok
def esperar(self, valor): if self.ver() != ('op', valor): raise Erro('mal_escrita') self.i += 1
def tudo(self): if not self.toks: raise Erro('mal_escrita') arvore = self.binaria(1) if self.i != len(self.toks): raise Erro('mal_escrita') return arvore
def binaria(self, minimo): esquerda = self.unaria() while True: tipo, op = self.ver() if tipo != 'op' or op not in PRECEDENCIA or PRECEDENCIA[op] < minimo: return esquerda self.i += 1 prec = PRECEDENCIA[op] direita = self.binaria(prec if op == '^' else prec + 1) esquerda = ('bin', op, esquerda, direita)
def unaria(self): tipo, valor = self.ver() if tipo == 'op' and valor in ('-', '+', 'not'): self.i += 1 return ('un', valor, self.unaria()) return self.primaria()
def primaria(self): tipo, valor = self.tirar() if tipo == 'numero': return ('num', float(valor) if '.' in valor else int(valor)) if tipo == 'texto': return ('str', valor[1:-1]) if tipo == 'op' and valor == 'π': return ('num', math.pi) if tipo == 'op' and valor == '(': arvore = self.binaria(1) self.esperar(')') return arvore if tipo == 'nome': minusculas = valor.lower() if minusculas in ('true', 'false'): return ('bool', minusculas == 'true') if minusculas == 'pi': return ('num', math.pi) if self.ver() == ('op', '('): self.i += 1 args = [] if self.ver() != ('op', ')'): args.append(self.binaria(1)) while self.ver() == ('op', ','): self.i += 1 args.append(self.binaria(1)) self.esperar(')') return ('call', valor, args) if self.ver() == ('op', '['): self.i += 1 indice = self.binaria(1) self.esperar(']') return ('idx', valor, indice) return ('var', valor) raise Erro('mal_escrita')
def expressao(texto): return Analisador(texto).tudo()
def destino(texto): """Uma variável ou uma posição de um vetor, onde se guarda um valor.""" arvore = expressao(texto) if arvore[0] not in ('var', 'idx'): raise Erro('destino') verificar_nome(arvore[1]) return arvore
# ----- Funções intrínsecas -----
def _num(nome, *valores): for v in valores: if not numero(v): raise Erro('arg_tipo', n=nome, t=nome_tipo(tipo_de(v)))
def _txt(nome, v): if not isinstance(v, str): raise Erro('arg_tipo', n=nome, t=nome_tipo(tipo_de(v)))
def _int(nome, v): if isinstance(v, bool) or not isinstance(v, int): raise Erro('arg_tipo', n=nome, t=nome_tipo(tipo_de(v)))
def _real(funcao): def f(nome, x): _num(nome, x) try: return float(funcao(x)) except (ValueError, OverflowError): raise Erro('impossivel') return f
def _char(nome, s, i): _txt(nome, s) _int(nome, i) if not 0 <= i < len(s): raise Erro('impossivel') return s[i]
def _tointeger(nome, v): if numero(v): return int(v) _txt(nome, v) if not re.fullmatch(r'\s*[-+]?\d+\s*', v): raise Erro('impossivel') return int(v)
def _toreal(nome, v): if numero(v): return float(v) _txt(nome, v) try: return float(v) except ValueError: raise Erro('impossivel')
def _tofixed(nome, r, i): _num(nome, r) _int(nome, i) if i < 0: raise Erro('impossivel') return format(r, f'.{i}f')
def _random(nome, n): _int(nome, n) if n <= 0: raise Erro('impossivel') return ALEATORIO.randrange(n)
def _tochar(nome, n): _int(nome, n) try: return chr(n) except (ValueError, OverflowError): raise Erro('impossivel')
def _tocode(nome, c): _txt(nome, c) if not c: raise Erro('impossivel') return ord(c[0])
def _abs(nome, n): _num(nome, n) return abs(n)
def _sgn(nome, n): _num(nome, n) return (n > 0) - (n < 0)
def _intf(nome, n): _num(nome, n) return int(n)
def _len(nome, s): _txt(nome, s) return len(s)
def _tostring(nome, v): return formatar(v)
INTRINSECAS = { 'abs': (1, _abs), 'arccos': (1, _real(math.acos)), 'arcsin': (1, _real(math.asin)), 'arctan': (1, _real(math.atan)), 'cos': (1, _real(math.cos)), 'sin': (1, _real(math.sin)), 'tan': (1, _real(math.tan)), 'int': (1, _intf), 'ln': (1, _real(math.log)), 'log': (1, _real(math.log)), 'log10': (1, _real(math.log10)), 'sgn': (1, _sgn), 'sqrt': (1, _real(math.sqrt)), 'len': (1, _len), 'char': (2, _char), 'tochar': (1, _tochar), 'tocode': (1, _tocode), 'tofixed': (2, _tofixed), 'tointeger': (1, _tointeger), 'toreal': (1, _toreal), 'tostring': (1, _tostring), 'random': (1, _random), 'size': (1, None), } ALEATORIO = random.Random(2026)
# ----- Variáveis -----
class Variavel: def __init__(self, tipo, tamanho=None): self.tipo = tipo self.vetor = tamanho is not None self.valor = [None] * tamanho if self.vetor else None
def converter(valor, tipo): """O valor pronto a guardar numa variável do tipo dado (como no Flowgorithm, um Real guardado num Inteiro perde a parte decimal). """ if tipo == 'integer' and numero(valor): return int(valor) if tipo == 'real' and numero(valor): return float(valor) if tipo == 'string' and isinstance(valor, str): return valor if tipo == 'boolean' and isinstance(valor, bool): return valor raise Erro('tipo_atribuicao', de=nome_tipo(tipo_de(valor)), para=nome_tipo(tipo))
# ----- As figuras -----
CAMPOS = { 'declare': ('names',), 'assign': ('var', 'expr'), 'input': ('var',), 'output': ('expr',), 'if': ('expr',), 'while': ('expr',), 'do': ('expr',), 'call': ('expr',), 'for': ('var', 'start', 'end'), 'comment': (), } NOME_CAMPO = {'names': 'campo_nomes', 'var': 'campo_variavel', 'expr': 'campo_expressao', 'start': 'campo_inicio', 'end': 'campo_fim', 'size': 'campo_tamanho'}
def texto_figura(no): """O texto que a figura mostra, para as mensagens.""" t = no.get('type') g = lambda k: str(no.get(k) or '').strip() if t == 'declare': tipo = nome_tipo(no.get('vtype')) if no.get('vtype') in TIPOS else '' nomes = g('names') if no.get('array'): nomes = ', '.join(f"{n.strip()}[{g('size')}]" for n in nomes.split(',')) return f"{tipo} {nomes}".strip() if nomes else '' if t == 'assign': return f"{g('var')} = {g('expr')}" if g('var') or g('expr') else '' if t == 'for': m = MENSAGENS[LINGUA] texto = f"{g('var')} = {g('start')} {m['ate_desc' if no.get('dir') == 'dec' else 'ate']} {g('end')}" if g('step') and g('step') != '1': texto += f" {m['palavra_passo']} {g('step')}" return texto if g('var') else '' if t == 'comment': return g('text') if t == 'input': return g('var') return g('expr')
class Figura: """Uma figura do fluxograma, já analisada."""
def __init__(self, no, funcao): self.tipo = no.get('type') if self.tipo not in CAMPOS: raise Erro('ilegivel', True) self.funcao = funcao self.texto = texto_figura(no) self.sim = [Figura(n, funcao) for n in no.get('yes', [])] if self.tipo == 'if' else [] self.nao = [Figura(n, funcao) for n in no.get('no', [])] if self.tipo == 'if' else [] self.corpo = [Figura(n, funcao) for n in no.get('body', [])] if self.tipo in ('while', 'for', 'do') else [] try: self.analisar(no) except Erro as erro: raise em_figura(self, erro)
def descricao(self): nome = MENSAGENS[LINGUA]['figuras'][self.tipo] onde = msg('figura', nome=nome, texto=self.texto) if self.texto else msg('figura_vazia', nome=nome) if self.funcao.lower() != 'main': onde = msg('na_funcao', f=self.funcao, onde=onde[:1].lower() + onde[1:]) return onde
def analisar(self, no): g = lambda k: str(no.get(k) or '').strip() for campo in CAMPOS[self.tipo]: if not g(campo): if all(not g(c) for c in CAMPOS[self.tipo]): raise Erro('sem_conteudo') raise Erro('falta_campo', campo=msg(NOME_CAMPO[campo])) t = self.tipo if t == 'declare': self.vtipo = no.get('vtype') if no.get('vtype') in TIPOS else 'integer' self.nomes = [verificar_nome(n.strip()) for n in g('names').split(',')] self.tamanho = None if no.get('array'): if not g('size'): raise Erro('falta_campo', campo=msg('campo_tamanho')) self.tamanho = expressao(g('size')) elif t == 'assign': self.destino = destino(g('var')) self.expr = expressao(g('expr')) elif t == 'input': self.destino = destino(g('var')) elif t in ('output', 'if', 'while', 'do'): self.expr = expressao(g('expr')) self.mudar_linha = no.get('newline', True) is not False elif t == 'call': arvore = expressao(g('expr')) if arvore[0] == 'var': arvore = ('call', arvore[1], []) if arvore[0] != 'call' or arvore[1].lower() in INTRINSECAS: raise Erro('chamar_so_funcoes') self.expr = arvore elif t == 'for': self.destino = expressao(g('var')) if self.destino[0] != 'var': raise Erro('destino') verificar_nome(self.destino[1]) self.inicio = expressao(g('start')) self.fim = expressao(g('end')) self.passo = expressao(g('step') or '1') self.descer = no.get('dir') == 'dec'
def em_figura(figura, erro): if erro.completo: return erro novo = Erro('em', True, onde=figura.descricao(), erro=str(erro)) return novo
class Funcao: def __init__(self, dados, principal): self.nome = str(dados.get('name') or '').strip() if principal: self.nome = 'Main' self.params = [] self.tipo = None self.retorno = '' if not principal: try: verificar_nome(self.nome) except Erro: raise Erro('funcao_nome', True, n=self.nome) vistos = set() for p in dados.get('params') or []: nome = str(p.get('name') or '').strip() try: verificar_nome(nome) except Erro: raise Erro('param_nome', True, f=self.nome, n=nome) if nome.lower() in vistos: raise Erro('param_nome', True, f=self.nome, n=nome) vistos.add(nome.lower()) tipo = p.get('type') if p.get('type') in TIPOS else 'integer' self.params.append((nome, tipo, bool(p.get('array')))) ret = dados.get('ret') or {} if ret.get('type') in TIPOS: self.tipo = ret['type'] self.retorno = str(ret.get('var') or '').strip() if not self.retorno: raise Erro('retorno_nome', True, f=self.nome) try: verificar_nome(self.retorno) except Erro: raise Erro('retorno_nome', True, f=self.nome) self.figuras = [Figura(n, self.nome) for n in dados.get('nodes') or []]
# ----- A execução -----
class Maquina: def __init__(self, funcoes, dados, max_passos): self.funcoes = {f.nome.lower(): f for f in funcoes} self.dados = dados self.proximo = 0 self.saida = [] self.passos = 0 self.max_passos = max_passos self.profundidade = 0
def passo(self): self.passos += 1 if self.passos > self.max_passos: raise Fim()
# Variáveis
def variavel(self, vars_, nome): var = vars_.get(nome.lower()) if var is None: raise Erro('nao_declarada', n=nome) return var
def ler_destino(self, vars_, arvore): """A variável e a posição (ou None) de um destino.""" var = self.variavel(vars_, arvore[1]) if arvore[0] == 'idx': if not var.vetor: raise Erro('nao_e_vetor', n=arvore[1]) return var, self.indice(vars_, var, arvore) if var.vetor: raise Erro('vetor_sem_indice', n=arvore[1]) return var, None
def indice(self, vars_, var, arvore): i = self.valor(vars_, arvore[2]) if isinstance(i, bool) or not isinstance(i, int): raise Erro('indice_inteiro') if not 0 <= i < len(var.valor): raise Erro('indice_fora', i=i, n=arvore[1], m=len(var.valor) - 1) return i
def guardar(self, vars_, arvore, valor): var, i = self.ler_destino(vars_, arvore) valor = converter(valor, var.tipo) if i is None: var.valor = valor else: var.valor[i] = valor
# Expressões
def valor(self, vars_, a): k = a[0] if k in ('num', 'str', 'bool'): return a[1] if k == 'var': var = self.variavel(vars_, a[1]) if var.vetor: raise Erro('vetor_sem_indice', n=a[1]) if var.valor is None: raise Erro('sem_valor', n=a[1]) return var.valor if k == 'idx': var = self.variavel(vars_, a[1]) if not var.vetor: raise Erro('nao_e_vetor', n=a[1]) i = self.indice(vars_, var, a) if var.valor[i] is None: raise Erro('elemento_sem_valor', i=i, n=a[1]) return var.valor[i] if k == 'call': return self.chamar(vars_, a[1], a[2], True) if k == 'un': v = self.valor(vars_, a[2]) if a[1] == 'not': if not isinstance(v, bool): raise Erro('op_logicos', op='not') return not v if not numero(v): raise Erro('op_numeros', op=a[1]) return -v if a[1] == '-' else v op = a[1] if op in ('and', 'or'): esquerda = self.valor(vars_, a[2]) if not isinstance(esquerda, bool): raise Erro('op_logicos', op=op) if (op == 'and' and not esquerda) or (op == 'or' and esquerda): return esquerda direita = self.valor(vars_, a[3]) if not isinstance(direita, bool): raise Erro('op_logicos', op=op) return direita x, y = self.valor(vars_, a[2]), self.valor(vars_, a[3]) if op == '&': return formatar(x) + formatar(y) if op in ('==', '!=', '<', '<=', '>', '>='): tx, ty = tipo_de(x), tipo_de(y) if not (numero(x) and numero(y)) and tx != ty: raise Erro('comparar', a=nome_tipo(tx), b=nome_tipo(ty)) if tx == 'boolean' and op not in ('==', '!='): raise Erro('comparar', a=nome_tipo(tx), b=nome_tipo(ty)) return {'==': x == y, '!=': x != y, '<': x < y, '<=': x <= y, '>': x > y, '>=': x >= y}[op] if not (numero(x) and numero(y)): raise Erro('op_numeros', op='mod' if op == '%' else op) try: if op == '+': return x + y if op == '-': return x - y if op == '*': return x * y if op == '/': if y == 0: raise Erro('divisao_zero') return x / y if op == '%': if y == 0: raise Erro('divisao_zero') resto = math.fmod(x, y) return int(resto) if isinstance(x, int) and isinstance(y, int) else resto resultado = float(x) ** y if isinstance(resultado, complex): raise Erro('impossivel') return float(resultado) except (OverflowError, ZeroDivisionError): raise Erro('impossivel')
def chamar(self, vars_, nome, args, em_expressao): minusculas = nome.lower() if minusculas in INTRINSECAS and minusculas not in self.funcoes: n, funcao = INTRINSECAS[minusculas] if len(args) != n: raise Erro('num_args', n=nome, k=n, d=len(args)) if minusculas == 'size': if args[0][0] != 'var': raise Erro('arg_tipo', n=nome, t='') var = self.variavel(vars_, args[0][1]) if not var.vetor: raise Erro('nao_e_vetor', n=args[0][1]) return len(var.valor) return funcao(nome, *[self.valor(vars_, a) for a in args]) f = self.funcoes.get(minusculas) if f is None or minusculas == 'main': raise Erro('funcao_desconhecida', n=nome) if em_expressao and f.tipo is None: raise Erro('sem_retorno', n=f.nome) if len(args) != len(f.params): raise Erro('num_args', n=f.nome, k=len(f.params), d=len(args)) novas = {} for k, ((pnome, ptipo, pvetor), arg) in enumerate(zip(f.params, args), 1): if pvetor: var = vars_.get(arg[1].lower()) if arg[0] == 'var' else None if var is None or not var.vetor or var.tipo != ptipo: raise Erro('arg_vetor', n=f.nome, k=k, t=nome_tipo(ptipo)) novas[pnome.lower()] = var # Os vetores passam por referência. else: v = self.valor(vars_, arg) try: v = converter(v, ptipo) except Erro: raise Erro('arg_tipo', n=f.nome, t=nome_tipo(tipo_de(v))) var = Variavel(ptipo) var.valor = v novas[pnome.lower()] = var self.profundidade += 1 if self.profundidade > 150: raise Erro('recursao') try: self.executar(f.figuras, novas) finally: self.profundidade -= 1 if f.tipo is None: return None var = novas.get(f.retorno.lower()) if var is None or var.vetor: raise Erro('em', True, onde=f.nome, erro=msg('retorno_nao_declarado', n=f.retorno)) if var.valor is None: raise Erro('em', True, onde=f.nome, erro=msg('retorno_sem_valor', n=f.retorno)) return converter(var.valor, f.tipo)
# Figuras
def executar(self, figuras, vars_): for figura in figuras: self.passo() try: self.executar_figura(figura, vars_) except Erro as erro: raise em_figura(figura, erro)
def condicao(self, vars_, arvore): v = self.valor(vars_, arvore) if not isinstance(v, bool): raise Erro('condicao') return v
def executar_figura(self, f, vars_): t = f.tipo if t == 'declare': tamanho = None if f.tamanho is not None: tamanho = self.valor(vars_, f.tamanho) if isinstance(tamanho, bool) or not isinstance(tamanho, int) or tamanho <= 0: raise Erro('tamanho_invalido') for nome in f.nomes: if nome.lower() in vars_: raise Erro('ja_declarada', n=nome) vars_[nome.lower()] = Variavel(f.vtipo, tamanho) elif t == 'assign': self.guardar(vars_, f.destino, self.valor(vars_, f.expr)) elif t == 'input': var, _ = self.ler_destino(vars_, f.destino) if self.proximo >= len(self.dados): raise Erro('mais_dados') texto = self.dados[self.proximo] self.proximo += 1 self.guardar(vars_, f.destino, ler_valor(texto, var.tipo)) elif t == 'output': self.saida.append(formatar(self.valor(vars_, f.expr)) + ('\n' if f.mudar_linha else '')) elif t == 'if': self.executar(f.sim if self.condicao(vars_, f.expr) else f.nao, vars_) elif t == 'while': while self.condicao(vars_, f.expr): self.executar(f.corpo, vars_) self.passo() elif t == 'do': while True: self.executar(f.corpo, vars_) self.passo() if not self.condicao(vars_, f.expr): break elif t == 'for': var, _ = self.ler_destino(vars_, f.destino) if var.tipo not in ('integer', 'real'): raise Erro('para_variavel') inicio = self.valor(vars_, f.inicio) fim = self.valor(vars_, f.fim) passo = self.valor(vars_, f.passo) for v in (inicio, fim): if not numero(v): raise Erro('op_numeros', op='=') if not numero(passo) or passo <= 0: raise Erro('passo') self.guardar(vars_, f.destino, inicio) while (var.valor >= fim) if f.descer else (var.valor <= fim): self.executar(f.corpo, vars_) self.passo() self.guardar(vars_, f.destino, var.valor - passo if f.descer else var.valor + passo) elif t == 'call': self.chamar(vars_, f.expr[1], f.expr[2], False) # O Comentário não faz nada na avaliação.
def ler_valor(texto, tipo): """Converte uma linha lida no tipo da variável, como faz o Flowgorithm.""" texto = texto.rstrip('\r') if tipo == 'string': return texto limpo = texto.strip() if tipo == 'integer' and re.fullmatch(r'[-+]?\d+', limpo): return int(limpo) if tipo == 'real' and re.fullmatch(r'[-+]?(\d+\.?\d*|\.\d+)([eE][-+]?\d+)?', limpo): return float(limpo) if tipo == 'boolean' and limpo.lower() in ('true', 'false'): return limpo.lower() == 'true' raise Erro('entrada_tipo', v=texto, t=MENSAGENS[LINGUA]['entrada_tipos'][tipo])
# ----- O fluxograma da resposta -----
def carregar(resposta): global LINGUA try: dados = json.loads(resposta) texto = dados.get('flowgorithm', [''])[0] fluxograma = json.loads(texto) if texto else {'functions': []} funcoes = fluxograma.get('functions') or [] if fluxograma.get('lang') in MENSAGENS: LINGUA = fluxograma['lang'] except (ValueError, KeyError, IndexError, TypeError, AttributeError): raise Erro('ilegivel', True) if not funcoes or not (funcoes[0].get('nodes') or len(funcoes) > 1): raise Erro('vazio', True) resultado = [Funcao(funcoes[0], True)] vistos = {'main'} for dados_funcao in funcoes[1:]: f = Funcao(dados_funcao, False) if f.nome.lower() in vistos: raise Erro('funcao_repetida', True, n=f.nome) vistos.add(f.nome.lower()) resultado.append(f) return resultado
def todas(figuras): for f in figuras: yield f yield from todas(f.sim) yield from todas(f.nao) yield from todas(f.corpo)
FIGURAS_PARAMETRO = {'entrada': {'input'}, 'saida': {'output'}, 'declarar': {'declare'}, 'atribuicao': {'assign'}, 'chamar': {'call'}, 'se': {'if'}, 'enquanto': {'while'}, 'para': {'for'}, 'fazer': {'do'}, 'comentario': {'comment'}, 'ciclo': {'while', 'for', 'do'}} # Os mesmos nomes noutras línguas. OUTROS_NOMES = {'input': 'entrada', 'output': 'saida', 'declare': 'declarar', 'assign': 'atribuicao', 'call': 'chamar', 'if': 'se', 'while': 'enquanto', 'for': 'para', 'do': 'fazer', 'comment': 'comentario', 'loop': 'ciclo', 'salida': 'saida', 'asignar': 'atribuicao', 'llamar': 'chamar', 'si': 'se', 'mientras': 'enquanto', 'hacer': 'fazer', 'comentario': 'comentario', 'bucle': 'ciclo'}
def verificar_parametros(funcoes, params): usadas = {f.tipo for fn in funcoes for f in todas(fn.figuras)} nomes = MENSAGENS[LINGUA]['figuras'] for chave in ('exigir', 'proibir'): for tipo in params.get(chave, []): tipo = str(tipo).lower() tipo = OUTROS_NOMES.get(tipo, tipo) if tipo not in FIGURAS_PARAMETRO: continue aceites = FIGURAS_PARAMETRO[tipo] nome = MENSAGENS[LINGUA]['ciclo'] if tipo == 'ciclo' else nomes[next(iter(aceites))] if chave == 'exigir' and not (aceites & usadas): raise Erro('exigir', True, nome=nome) if chave == 'proibir' and (aceites & usadas): raise Erro('proibir', True, nome=nome) definidas = {f.nome.lower() for f in funcoes[1:]} for nome in params.get('funcoes', []): if str(nome).lower() not in definidas: raise Erro('exigir_funcao', True, n=nome)
__maquina__ = None try: __funcoes__ = carregar(__answer__) verificar_parametros(__funcoes__, __params__) __maquina__ = Maquina(__funcoes__, sys.stdin.read().splitlines(), int(__params__.get('max_passos', 100000))) __maquina__.executar(__funcoes__[0].figuras, {}) print(''.join(__maquina__.saida), end='') except (Erro, Fim, RecursionError) as __erro__: __feito__ = ''.join(__maquina__.saida) if __maquina__ else '' if __feito__ and not __feito__.endswith('\n'): __feito__ += '\n' if isinstance(__erro__, Fim): __texto__ = msg('nao_termina') elif isinstance(__erro__, RecursionError): __texto__ = msg('recursao') else: __texto__ = str(__erro__) print(__feito__ + '*** ' + __texto__)
